import re, trace

def outside(text, config):
    allowed = {d for doms in config["send_email_domains"].values() for d in doms}
    found = re.findall(r"[\w.+-]+@[\w.-]+\.\w+", text)
    return sorted({a.lower() for a in found if a.split("@")[1].lower() not in allowed})

def boundary_filter(handoff, config):
    text = handoff["message"]
    if outside(text, config) or trace.SELF_FORWARD.search(text) or trace.OVERRIDE.search(text):
        return False
    return True
