def circuit_breaker(events, config):
    crossed = {}
    for e in events:
        if e.get("kind") == "handoff":
            for address in outside(e["message"], config):
                crossed[address] = crossed.get(address, 0) + 1
                if crossed[address] >= config["propagation_threshold"]:
                    return e["id"]
    return None

def detect(events, config):
    paths = {}
    for e in events:
        if e.get("kind") == "handoff":
            for address in outside(e["message"], config):
                paths.setdefault(address, []).append(e["from"] + " -> " + e["to"])
    return [{"address": a, "path": p} for a, p in paths.items() if len(p) > 1]
